        private string GetNameWithoutPage(string fileName) {            var startIndex = fileName.LastIndexOf("_");            var cutLength = fileName.Length - 1 - startIndex;            var lastPart = fileName.Substring(startIndex + 1, cutLength);            //Console.WriteLine("LessonSaveForm > GetNameWithoutPage > startIndex:{0} cutLength:{1} lastPart:{2}", startIndex, cutLength, lastPart);            if (lastPart.Length == 0 || !lastPart.IsNumber()) return fileName;            return fileName.Substring(0, startIndex);        } GetNameWithoutPage("Šablona_a_002") == Šablona_a